-- Extraction invariants. Generated by drizzle-kit, then reordered and extended
-- by hand. The reordering is not cosmetic: drizzle-kit emitted the composite
-- foreign key on atoms before the unique constraint it references, which does
-- not apply. The hand-written additions are at the foot of the file.
--
-- Nothing here calls a model. This is the half of phase 1 that is schema, and
-- it closes two defects that shipped in phase 0: an atom could name document A
-- and a section of document B, and a quote could claim a span that did not
-- contain it.
CREATE TYPE "public"."extraction_status" AS ENUM('running', 'succeeded', 'failed');--> statement-breakpoint
CREATE TABLE "atom_suppressions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"project_id" uuid NOT NULL,
	"section_id" uuid NOT NULL,
	"statement" text NOT NULL,
	"reason" text NOT NULL,
	"similarity" double precision,
	"duplicate_of_atom_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "atom_suppressions_reason_not_blank" CHECK (length(btrim(reason)) > 0)
);
--> statement-breakpoint
ALTER TABLE "atom_suppressions" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "section_extractions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"section_id" uuid NOT NULL,
	"extractor_version" text NOT NULL,
	"section_hash" text NOT NULL,
	"status" "extraction_status" DEFAULT 'running' NOT NULL,
	"error" text,
	"started_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finished_at" timestamp with time zone,
	CONSTRAINT "section_extractions_section_version_key" UNIQUE("section_id","extractor_version"),
	CONSTRAINT "section_extractions_finished_iff_terminal" CHECK ((status = 'running') = (finished_at IS NULL))
);
--> statement-breakpoint
