-- ─── Hand-written: what drizzle-kit cannot express ───────────────────────────
--
-- The ordinal key, restated as a DEFERRABLE constraint. It was a unique index,
-- and Postgres cannot defer an index. putDocument now moves sections rather
-- than deleting and re-inserting them, and moving one from ordinal 4 to
-- ordinal 2 collides with the row already at 2 partway through the statement
-- sequence. INITIALLY IMMEDIATE, so every other writer sees the behaviour it
-- had before; only a transaction that says SET CONSTRAINTS ... DEFERRED gets
-- the slack.
ALTER TABLE "document_sections"
	ADD CONSTRAINT "document_sections_document_ordinal_key"
	UNIQUE ("document_id", "ordinal") DEFERRABLE INITIALLY IMMEDIATE;--> statement-breakpoint

-- Verbatim quote verification. This cannot be a CHECK constraint: a CHECK may
-- not read another table, and the text an atom quotes lives in
-- document_sections. So it is a trigger, and the comparison is exactly the one
-- docs/05-extraction.md gives as the phase-1 exit gate — the same expression,
-- run on write instead of audited afterwards.
--
-- int4range is half-open and zero-based; substring() is 1-based and takes a
-- length. Hence the + 1 on the start and the subtraction for the length.
-- Offsets are Unicode code points, because substring() on text counts
-- characters — not bytes, and not UTF-16 code units.
--
-- SECURITY INVOKER, deliberately. The foreign key above proves the section row
-- exists, but referential integrity checks bypass row-level security — so
-- without this, an actor could cite a section it may not read and learn from
-- the outcome whether its guess at the quote was right. Here, a section the
-- caller cannot see is a rejected write.
--
-- What this does not cover: a section body edited underneath an atom. Nothing
-- updates a body in place — putDocument replaces the rows whose hash moved, and
-- the atoms cascade away with them.
CREATE OR REPLACE FUNCTION "standfast_verify_atom_quote"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
	section_body text;
BEGIN
	-- Nothing to verify when the citation is simply absent. Both columns are
	-- NOT NULL and a BEFORE trigger runs ahead of that check, so without this
	-- the row is rejected for "section <NULL> is not readable" — true, useless,
	-- and hiding the constraint that actually has something to say.
	IF new."section_id" IS NULL OR new."document_id" IS NULL THEN
		RETURN new;
	END IF;

	SELECT s."body" INTO section_body
	FROM "document_sections" s
	WHERE s."id" = new."section_id" AND s."document_id" = new."document_id";

	-- Two failures share this message, and neither can be distinguished without
	-- telling the caller something it is not entitled to know: the section
	-- belongs to a different document, or it belongs to a different tenant.
	IF NOT FOUND THEN
		RAISE EXCEPTION 'section % is not a readable section of document %',
			new."section_id", new."document_id"
			USING ERRCODE = 'check_violation';
	END IF;

	IF substring(section_body
	             from lower(new."source_span") + 1
	             for  upper(new."source_span") - lower(new."source_span"))
	   IS DISTINCT FROM new."source_quote"
	THEN
		RAISE EXCEPTION 'source_quote does not match span % of section %',
			new."source_span", new."section_id"
			USING ERRCODE = 'check_violation';
	END IF;

	RETURN new;
END;
$$;--> statement-breakpoint

CREATE TRIGGER "atoms_verify_quote_insert"
	BEFORE INSERT ON "atoms"
	FOR EACH ROW EXECUTE FUNCTION "standfast_verify_atom_quote"();--> statement-breakpoint

-- The WHEN clause keeps an unrelated update — writing the embedding, ratifying,
-- superseding — from paying for a lookup that cannot have changed the answer.
CREATE TRIGGER "atoms_verify_quote_update"
	BEFORE UPDATE ON "atoms"
	FOR EACH ROW
	WHEN (old."source_quote" IS DISTINCT FROM new."source_quote"
	   OR old."source_span"  IS DISTINCT FROM new."source_span"
	   OR old."section_id"   IS DISTINCT FROM new."section_id"
	   OR old."document_id"  IS DISTINCT FROM new."document_id")
	EXECUTE FUNCTION "standfast_verify_atom_quote"();--> statement-breakpoint

-- FORCE, not just ENABLE. Without it the table owner bypasses every policy
-- silently, and schema-guards.integration.test.ts asserts it on every table in
-- WIRE_ALLOWLIST — which these two now are.
ALTER TABLE "section_extractions" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "atom_suppressions" FORCE ROW LEVEL SECURITY;--> statement-breakpoint

-- A policy restricts which rows a role may touch. It does not grant the
-- privilege to touch the table at all.
GRANT SELECT, INSERT, UPDATE, DELETE ON "section_extractions" TO "standfast_app";--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "atom_suppressions" TO "standfast_app";
